RSpec.describe "Timekeeping::LocalOwner contract adapter" do
  # "No production code accepts a token in place of the gateway's user."
  it "keeps token handling for the local owner in spec support and out of production code" do
    expect(Rails.root.join("spec/support/timekeeping/local_owner_arrange.rb")).to exist

    production_files = Dir[Rails.root.join("{app,lib}/**/*.rb")]
    offenders = production_files.select do |path|
      File.read(path).match?(/LocalOwnerClient|LocalOwnerArrange|local_owner_arrange/)
    end
    expect(offenders).to be_empty

    parameter_names = Timekeeping::LocalOwner.method(:call).parameters.map(&:last)
    expect(parameter_names).not_to include(:token, :bearer_token, :authorization)
  end
end

